function icon(name,size=20){const paths={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="3"/><path d="M8 7V4h8v3M3 12h18M10 12v3h4v-3"/>',apps:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4V2h6v2M9 10h6M9 14h6M9 18h4"/>',message:'<path d="M21 11a8 8 0 0 1-8 8H7l-5 3 2-6a8 8 0 0 1-1-5 9 9 0 0 1 18 0Z"/><path d="M7 10h10M7 14h6"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',resume:'<path d="M14 2H5v20h14V7l-5-5Zm0 0v5h5M8 11h8M8 15h8M8 18h5"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3ZM20 2v4M18 4h4"/>',route:'<circle cx="5" cy="5" r="2"/><circle cx="19" cy="19" r="2"/><path d="M7 5h8a4 4 0 0 1 0 8H9a4 4 0 0 0 0 8h8"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',save:'<path d="M6 3h12v19l-6-4-6 4Z"/>',send:'<path d="m3 3 19 9L3 21l4-9-4-9Zm4 9h15"/>',plus:'<path d="M12 4v16M4 12h16"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',archive:'<rect x="3" y="3" width="18" height="5" rx="1"/><path d="M5 8v13h14V8M9 12h6"/>',link:'<path d="m9 15 6-6M8 16l-2 2a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0m4 0 2-2a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0"/>',check:'<path d="m5 12 4 4L20 5"/>'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.briefcase}</svg>`}
function workspaceNav(page){if(isOrganizationAccount())return `<span class="nav-caption">HIRING WORKSPACE</span><a href="#organization" class="${page==='organization'?'active':''}">${icon('briefcase')}<span>Hiring portal</span></a><a href="#settings" class="${page==='settings'?'active':''}">${icon('settings')}<span>Account settings</span></a>`;const links=[['overview','route','Overview'],['explore','briefcase','Find work'],['projects','apps','Applications'],['messages','message','Messages'],['profile','user','My profile'],['resume','resume','Resume & match'],['recommend','spark','Project ideas']];const link=([p,i,t])=>`<a href="#${p}" class="${page===p||page.startsWith('project/')&&p==='explore'||page==='recommend/results'&&p==='recommend'?'active':''}" ${page===p?'aria-current="page"':''}>${icon(i)}<span>${t}</span>${p==='messages'&&unreadCount()?`<b class="nav-unread">${unreadCount()}</b>`:''}</a>`;return `<span class="nav-caption">YOUR WORKSPACE</span>${links.map(link).join('')}<details class="nav-more" ${['skills','career'].includes(page)?'open':''}><summary>Career tools <span>⌄</span></summary>${[['skills','spark','Skills check'],['career','route','Career plan']].map(link).join('')}</details><a href="#tools" class="premium-nav ${page==='tools'?'active':''}">${icon('spark')}<span>Career toolkit</span><small>Free</small></a><a href="#premium" class="premium-nav ${['premium','checkout'].includes(page)?'active':''}">${icon('spark')}<span>Premium workspace</span><small>${typeof paperActive==='function'&&paperActive()?'Test active':'Preview'}</small></a><a class="settings-nav ${page==='settings'?'active':''}" href="#settings">${icon('settings')}<span>Workspace settings</span></a>`}
function nextSteps(){return `<div class="next-steps"><a href="#explore">${icon('search')}<div><b>1. Find your project</b><small>Browse paid opportunities</small></div></a><a href="#resume">${icon('eye')}<div><b>2. Check your fit</b><small>See your resume evidence</small></div></a><a href="#projects">${icon('send')}<div><b>3. Make your move</b><small>Apply & track your work</small></div></a></div>`}
function workspaceSettings(){if(isOrganizationAccount())return title('Organization account settings','Manage your hiring account and sign-in settings.')+accountPanel();return title('Workspace settings','Manage your account and workspace data.')+(typeof Account!=='undefined'?accountPanel():'')+`<section class="panel wide-panel settings-panel"><h2>Workspace data</h2><p>Your profile, resume, saved projects, and application drafts are saved to your account. Messages are not delivered to real people and applications are not sent to employers. Messages and career-tool previews are not live services. There is no live presence.</p><h3>Nextwork brand assets</h3><p>The uploaded Nextwork icon and original wordmark lockups.</p><div class="brand-downloads"><a class="outline" href="assets/brand/nextwork-icon.png" download>App icon ↓</a><a class="outline" href="assets/brand/nextwork-wordmark-primary.png" download>Primary lockup ↓</a><a class="outline" href="assets/brand/nextwork-wordmark-reversed.png" download>Reversed lockup ↓</a></div><h3>Resume review</h3><p>Instant matching runs locally. Optional Gemini analysis uses the configured free-tier key only after you explicitly consent.</p><a class="outline" href="#resume">Open resume review →</a></section>`}
function tidyWorkspace(){const area=$('#app');area.querySelectorAll('[data-workspace-note]').forEach(x=>x.remove());area.querySelectorAll('.notice,.trust').forEach(el=>{if(/demo|sample opportunity|sample marketplace|stored locally|not a signed-in|not shared with|does not contact|not sent to|saved locally|saved on this device/i.test(el.textContent))el.remove()});area.querySelectorAll('.tag').forEach(el=>{if(/sample marketplace listing|application saved locally/i.test(el.textContent))el.textContent=el.textContent.includes('Application')?'Application saved':'Project'});}
